import { Tile } from '@/components/ui/tile'
import { TILE_THEMES, type TileTone } from '@/lib/tokens'

export interface DotMatrixCardProps {
  label: string
  subLabel?: string
  active: number
  total: number
  tone?: TileTone
}

export function DotMatrixCard({
  label,
  subLabel,
  active,
  total,
  tone = 'lilac',
}: DotMatrixCardProps) {
  const theme = TILE_THEMES[tone]
  const cols = total > 10 ? 10 : Math.max(total, 5)
  return (
    <Tile size="s" tone={tone}>
      <span
        className="flex items-center justify-between gap-2 text-[14px] font-medium"
        style={{ color: theme.soft }}
      >
        <span className="truncate">{label}</span>
        {subLabel && <span className="shrink-0 whitespace-nowrap">{subLabel}</span>}
      </span>
      <span className="font-glaze-display text-[44px] leading-11.5 font-extrabold tracking-[-0.02em] whitespace-nowrap">
        {active}
        <span style={{ opacity: 0.48 }}>/{total}</span>
      </span>
      <span
        aria-hidden="true"
        className="grid justify-items-center gap-1.5"
        style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}
      >
        {Array.from({ length: total }, (_, i) => (
          <span
            key={i}
            className="h-3.5 w-3.5 rounded-full"
            style={{
              backgroundColor: i < active ? theme.accent : theme.track,
            }}
          />
        ))}
      </span>
    </Tile>
  )
}

import { GaugeChart } from '@/components/ui/radial-chart'
import { Tile } from '@/components/ui/tile'
import { TILE_THEMES, type TileTone } from '@/lib/tokens'

export interface GaugeCardProps {
  label: string
  subLabel?: string
  percent: number
  description: string
  tone?: TileTone
  accentColor?: string
}

export function GaugeCard({
  label,
  subLabel,
  percent,
  description,
  tone = 'white',
  accentColor,
}: GaugeCardProps) {
  const theme = TILE_THEMES[tone]
  const clamped = Math.max(0, Math.min(100, percent))

  return (
    <Tile size="s" tone={tone}>
      <span
        className="flex items-center justify-between gap-2 text-[14px] font-medium"
        style={{ color: theme.soft }}
      >
        <span className="truncate">{label}</span>
        {subLabel && <span className="shrink-0 whitespace-nowrap">{subLabel}</span>}
      </span>
      <div className="self-center">
        <GaugeChart
          value={clamped}
          max={100}
          label={label}
          valueText={`${clamped}%`}
          variant="semicircle"
          color={accentColor ?? theme.accent}
          trackColor={theme.track}
          tone={tone}
          width={142}
          height={82}
          barSize={12}
        />
      </div>
      <span className="truncate text-center text-[13px]" style={{ color: theme.soft }}>
        {description}
      </span>
    </Tile>
  )
}

import { SparkChart } from '@/components/ui/spark-chart'
import { Tile } from '@/components/ui/tile'
import { SEMANTIC_TOKENS, TILE_THEMES, type Status, type TileTone } from '@/lib/tokens'

export interface TrendCardProps {
  label: string
  value: string | number
  unit?: string
  delta: string
  deltaStatus?: Status
  points?: number[]
  tone?: TileTone
  strokeColor?: string
}

export function TrendCard({
  label,
  value,
  unit,
  delta,
  deltaStatus = 'normal',
  points = [75, 70, 78, 60, 48, 55, 36, 42, 22, 26],
  tone = 'white',
  strokeColor,
}: TrendCardProps) {
  const theme = TILE_THEMES[tone]
  const pill = SEMANTIC_TOKENS[deltaStatus]

  return (
    <Tile size="s" tone={tone}>
      <span
        className="flex items-center justify-between text-[14px] font-medium"
        style={{ color: theme.soft }}
      >
        <span>{label}</span>
        <span
          className="rounded-full px-2 py-0.5 text-[12px] font-semibold"
          style={{ backgroundColor: pill.pillBg, color: pill.ink }}
        >
          {delta}
        </span>
      </span>
      <span className="flex items-baseline gap-1.5">
        <span className="font-glaze-display text-[44px] leading-11.5 font-extrabold tracking-[-0.03em]">
          {value}
        </span>
        {unit && (
          <span className="text-[14px] font-semibold" style={{ color: theme.soft }}>
            {unit}
          </span>
        )}
      </span>
      <SparkChart
        data={points}
        variant="line"
        color={strokeColor ?? theme.accent}
        label={label}
        unit={unit}
        tone={tone}
        height={36}
      />
    </Tile>
  )
}

