import * as React from 'react'
import { Tile } from '@/components/ui/tile'
import { TILE_THEMES, type TileTone } from '@/lib/tokens'

export interface ClockCardProps {
  weekday?: string
  time?: string
  dateText?: string
  live?: boolean
  tone?: TileTone
}

export function ClockCard({
  weekday,
  time,
  dateText,
  live = false,
  tone = 'periwinkle',
}: ClockCardProps) {
  const theme = TILE_THEMES[tone]
  const [now, setNow] = React.useState(() => new Date())

  React.useEffect(() => {
    if (!live) return
    const id = window.setInterval(() => setNow(new Date()), 1000)
    return () => window.clearInterval(id)
  }, [live])

  const weekdays = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六']
  const displayWeekday = weekday ?? weekdays[now.getDay()]
  const displayTime =
    time ??
    `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`
  const displayDate =
    dateText ??
    `${now.getFullYear()} 年 ${now.getMonth() + 1} 月 ${now.getDate()} 日`

  return (
    <Tile size="s" tone={tone}>
      <span className="text-[14px] font-medium" style={{ color: theme.soft }}>
        {displayWeekday}
      </span>
      <span className="font-glaze-display text-[56px] xl:text-[60px] leading-15.5 font-extrabold tracking-[-0.03em]">
        {displayTime}
      </span>
      <span className="text-[13px]" style={{ color: theme.soft }}>
        {displayDate}
      </span>
    </Tile>
  )
}

import { BatteryCharging } from '@phosphor-icons/react'
import { Tile } from '@/components/ui/tile'
import { TILE_THEMES, type TileTone } from '@/lib/tokens'

export function BatteryCard({
  device,
  percent,
  charging = false,
  remaining,
  tone = 'mint',
}: {
  device: string
  percent: number
  charging?: boolean
  remaining: string
  tone?: TileTone
}) {
  const theme = TILE_THEMES[tone]
  const filled = Math.round((percent / 100) * 5)
  return (
    <Tile size="s" tone={tone} className="justify-between">
      <div className="flex items-center justify-between">
        <span className="text-[14px] font-medium" style={{ color: theme.soft }}>
          {device}
        </span>
        {charging && (
          <BatteryCharging size={18} weight="fill" style={{ color: theme.accent }} />
        )}
      </div>
      <div className="font-glaze-display text-[44px] leading-none font-extrabold tracking-[-0.03em]">
        {percent}%
      </div>
      <div className="flex flex-col gap-1.5">
        <div className="grid grid-cols-5 gap-1.5">
          {[0, 1, 2, 3, 4].map((i) => (
            <div
              key={i}
              className="h-2 rounded-full"
              style={{
                backgroundColor: i < filled ? theme.accent : theme.track,
              }}
            />
          ))}
        </div>
        <span className="text-[12px]" style={{ color: theme.soft }}>
          {remaining}
        </span>
      </div>
    </Tile>
  )
}

