              >
                <span>{a.label}</span>
                <span className="font-glaze-mono text-[10px]" style={{ color: theme.soft }}>
                  {a.shortcut}
                </span>
              </button>
            ))}
          </div>
        </div>
      </Tile>

      <CommandDialog
        open={open}
        onOpenChange={(next) => {
          setOpen(next)
          if (!next) setQuery('')
        }}
        title="快捷指令面板"
        description="搜索并执行快捷命令"
        maxWidth="520px"
      >
        <CommandInput
          autoFocus
          value={query}
          onValueChange={setQuery}
          placeholder={placeholder}
        />
        <CommandList>
          <CommandEmpty>未找到匹配的指令</CommandEmpty>
          <CommandGroup heading="快捷指令">
            {quickActions.map((a) => (
              <CommandItem
                key={a.label}
                value={a.label}
                keywords={[a.shortcut]}
                onSelect={() => {
                  onAction?.(a.label)
                  setOpen(false)
                  setQuery('')
                }}
              >
                <span className="font-semibold">{a.label}</span>
                <CommandShortcut>{a.shortcut}</CommandShortcut>
              </CommandItem>
            ))}
          </CommandGroup>
        </CommandList>
        <CommandFooter>
          <span>↑↓ 选择 · Enter 执行 · Esc 关闭</span>
          <span>{quickActions.length} 条快捷指令</span>
        </CommandFooter>
      </CommandDialog>
    </>
  )
}

